"""Element-wise subtraction of 2 vectors where the second vector is
    subtracted from the first. Return `x1 - x2`.

    Args:
        x1 (list): First vector. 1 or 2 dimensional.
        x2 (list): Second vector. Same dimenions as `x1`.

    Returns:
        list: A element-wise subtracted list. Same dimensions as `x1`.
    """
def sub(x1: list[float] | list[list[float]], x2: list[float] | list[list[float]]) -> list[float] | list[list[float]] {
    assert len(x1) == len(x2);
    if isinstance(x1[0], list) {
        rows_x1 = x1 as list[list[float]];
        rows_x2 = x2 as list[list[float]];
        assert len(rows_x1[0]) == len(rows_x2[0]);
        diff: list[list[float]] = [];
        for (x1_i, x2_i) in zip(rows_x1, rows_x2) {
            diff_i = [(x1_ij - x2_ij) for (x1_ij, x2_ij) in zip(x1_i, x2_i)];
            diff.append(diff_i);
        }
        return diff;
    }
    vec_x1 = x1 as list[float];
    vec_x2 = x2 as list[float];
    return [(x1_i - x2_i) for (x1_i, x2_i) in zip(vec_x1, vec_x2)];
}

"""Removes the extra brackets when outputting a list of lists
       into a csv file.

    Args:
        masterList: input list of lists

    Returns:
    list: output list
    """
def output_list(master_list: Any) -> object {
    output = [];
    for item in master_list {
        if isinstance(item, `list) {
            for i in output_list(item) {
                output.append(i);
            }
        } else {
            output.append(item);
        }
    }
    return output;
}

"""
    Determine the chromosomes in a cluster of hotspot regions
    """
def chromosomesInCluster(cluster: list[dict[str, str | int]]) -> dict[str, tuple[int, int]] {
    chromosomes: dict[str, tuple[int, int]] = dict();
    for point in cluster {
        chromosome = point['chromosome'] as str;
        position = point['position'] as int;
        if chromosome in chromosomes {
            (start, end) = chromosomes[chromosome];
            chromosomes[chromosome] = (min(start, position), max(end, position + 1));
        } else {
            chromosomes[chromosome] = (position, position + 1);
        }
    }
    return chromosomes;
}

"""Returns a string with all digits removed."""
def remove_digits(s: str) -> str {
    return ''.join(filter(lambda (x: str) { not x.isdigit(); }, s));
}

"""Split into kernel variables and not."""
def split_kernel_vars(var_couple: list[tuple[str, int]], count: int) -> list[str] {
