"""Normalize Paizo HTML attribute names to a canonical form."""
def normalize_attribute(attr: str) -> str {
    attr = attr.strip();
    if attr.endswith(':') {
        attr = attr[:-1];
    }
    if attr == 'Prerequisites' {
        attr = 'Prerequisite';
    }
    if attr == 'Note' {
        attr = 'Prerequisite';
    }
    if attr == 'Benefits' {
        attr = 'Benefit';
    }
    if attr == 'Leadership Modifiers' {
        attr = 'Benefit';
    }
    assert attr in ('Prerequisite', 'Benefit', 'Normal', 'Special');
    return attr.lower();
}

"""Whether both position are equal in the given tuples."""
def _is_equal_position(first: tuple[object, ...], second: tuple[object, ...], position: int) -> bool {
    if len(first) > position {
        if len(second) > position {
            return first[position] == second[position];
        }
        return first[position] is None;
    }
    if len(second) > position {
        return second[position] is None;
    }
    return True;
}

