"""Get the 3-vector of coordinates from the site index."""
def get_coord(site: int, L: list[int]) -> list[int] {
    x = site // (L[1] * L[2]);
    yz = site % (L[1] * L[2]);
    y = yz // L[2];
    z = yz % L[2];
    return [x, y, z];
}

"""

    Add the super group id based on the *super_group_ids* dict and the
    treatment.
    """
def add_super_group_id(
    individual_group_id: str,
    super_group_ids: dict[str, list[str]],
    treatment: str
) -> str | None {
    if treatment in ['1H1A', '1H2A'] {
        return individual_group_id;
    }
    for (sg_id, group_ids) in super_group_ids.items() {
        if individual_group_id in group_ids {
            return sg_id;
        }
    }
}

"""
    Parse the GID given and return a tuple with the following values:

    - The real GID without bitwise flags.
    - Whether or not the tile is horizontally flipped.
    - Whether or not the tile is vertically flipped.
    - Whether or not the tile is "diagonally" flipped.

    This is a low-level function used internally by this library; you
    don't typically need to use it.
    """
def t_gid_parse(gid: Any) -> object {
    rgid = gid - (gid & (1 << 31)) - (gid & (1 << 30)) - (gid & (1 << 29));
    hflip = bool((gid & (1 << 31)));
    vflip = bool((gid & (1 << 30)));
    dflip = bool((gid & (1 << 29)));
    return (rgid, hflip, vflip, dflip);
}

"""
    Checks if a packet is a magic packet, returns
    True or False.

    Args:
        data (bytes): the payload from a packet

    """
def is_magic_packet(data: bytes) -> bool {
    hex_data = data.hex().lower();
    sync = hex_data[:12];
    if sync == 'f' * 12 {
        mac = hex_data[12:24];
        magic = sync + (mac * 16);
        if len(hex_data) == len(magic) {
            return magic == hex_data;
        }
        return magic == hex_data[:-12];
    }
    return False;
}

"""Search a number in a list using binary search."""
def search(target: int, prime_list: list[int]) -> bool {
    (left, right) = (0, len(prime_list) - 1);
    while left <= right {
        middle = (left + right) // 2;
        if prime_list[middle] == target {
            return True;
        } elif prime_list[middle] < target {
            left = middle + 1;
        } else {
            right = middle - 1;
        }
    }
    return False;
}

"""For chunks of fps number of frames for actual as well as predicted viewports."""
def get_chunks(
    act_viewport: list[object],
    pred_viewport: list[object],
    frame_nos: list[object],
    max_frame: int,
    fps: int
) -> tuple[list[list[object]], list[list[object]], list[list[object]]] {
    act_tiles: list[list[object]] = [];
    pred_tiles: list[list[object]] = [];
    chunk_frames: list[list[object]] = [];
    chunk_size = fps;
    number_of_chunks = int(len(act_viewport) / chunk_size);
    for i in range(number_of_chunks) {
        start = i * chunk_size;
        end = (i + 1) * chunk_size;
        act_tiles.append(act_viewport[start:end]);
        pred_tiles.append(pred_viewport[start:end]);
        chunk_frames.append(frame_nos[start:end]);
    }
    remainder_start = number_of_chunks * chunk_size;
    act_tiles.append(act_viewport[remainder_start:]);
    pred_tiles.append(pred_viewport[remainder_start:]);
    chunk_frames.append(frame_nos[remainder_start:]);
    return (act_tiles, pred_tiles, chunk_frames);
}

"""Return padded key string used in AES encrypt function."""
def aes_key_pad(key: str) -> str {
    if not key {
        raise ValueError('Key should not be empty!');
    }
    aes_key_length = 32;
    while len(key) < aes_key_length {
        key += key;
    }
    return key[:aes_key_length];
}

