"""Return True if 'c' is a control character.

    c is considered a control character if
    it is outside of the extended ASCII set or
    has a code below 32 with some exclusions.
    An ASCII compatible character set is assumed.
    """
def is_control_char(c: Any) -> object {
    charcode = 0;
    try {
        charcode = ord(c);
    } except TypeError {
        charcode = c;
    }
    excludes = ("\t", "\r", "\n");
    if (charcode in [ord(char) for char in excludes]) {
        return False;
    }
    return ((charcode < 32) or (charcode > 255));
}

"""Returns functor that unfolds recursion.

  Example:
  P_r0 := P_recursive_head(P_recursive: nil);
  P_r1 := P_recursive_head(P_recursive: P_r0);
  P_r2 := P_recursive_head(P_recursive: P_r1);
  P_r3 := P_recursive_head(P_recursive: P_r2);
  P := P_r3();
  """
def GetRecursionFunctor(depth: Any) -> object {
    result_lines = ['P_r0 := P_recursive_head(P_recursive: nil);'];
    for i in range(depth) {
        result_lines.append(
            'P_r{1} := P_recursive_head(P_recursive: P_r{0});'.format(i, (i + 1))
        );
    }
    result_lines.append('P := P_r{0}();'.format(depth));
    return '\n'.join(result_lines);
}

"""
  Finds the smallest positive integer not in array.
  The smallest possible answer is 1.
  """
def solution(array: list[int]) -> int {
    i = 1;
    visited = [];
    for value in array {
        visited.append(value);
        if value == i {
            while True {
                value += 1;
                if value not in visited {
                    break;
                }
            }
            i = value;
        }
    }
    return i;
}

"""Cube of x."""
def cube(x: Any) -> object {
