"""See setCounters() / getCounters() methods in IJ source, ij/gui/PointRoi.java."""
def get_counter(data: list[int], base: int) -> tuple[int, int] {
    _ = data[base];
    b1 = data[base + 1];
    b2 = data[base + 2];
    b3 = data[base + 3];
    counter = b3;
    position = (b1 << 8) + b2;
    return (counter, position);
}

"""
    Now, the jumps are even stranger: after each jump, if the offset was three or more,
    instead decrease it by 1. Otherwise, increase it by 1 as before.

    Using this rule with the above example, the process now takes 10 steps,
    and the offset values after finding the exit are left as 2 3 2 3 -1.

    How many steps does it now take to reach the exit?
    """
def part2(input_lines: list[str]) -> int {
    jumps = [int(line) for line in input_lines];
    def jump(at: int) -> int {
        to = at + jumps[at];
        if jumps[at] > 2 {
            jumps[at] -= 1;
        } else {
            jumps[at] += 1;
        }
        return to;
    }
    pos = 0;
    count = 0;
    while pos >= 0 and pos < len(jumps) {
        count += 1;
        pos = jump(pos);
    }
    return count;
}

"""
    Take a string referring to an age group and find it's upper and lower limits.

    Args:
        age_string: The string to be analysed
    Returns:
        limits: List of the lower and upper limits
        dict_limits: Dictionary of the lower and upper limits
    """
def interrogate_age_string(age_string: Any) -> object {
    assert (age_string[:4] == '_age') , 'Age string does not begin with "_age".';
    ages = age_string[4:];
    lower_age_limit = '';
    for (i, letter) in enumerate(ages) {
        if letter.isdigit() {
            lower_age_limit += letter;
        } else {
            break;
        }
    }
    remaining_string = ages[len(lower_age_limit):];
    if (lower_age_limit != '') {
        lower_age_limit = float(int(lower_age_limit));
    }
    if (remaining_string == 'up') {
        upper_age_limit = float('inf');
    } elif (remaining_string[:2] == 'to') {
        upper_age_limit = float(remaining_string[2:]);
    } else {
        raise NameError('Age string incorrectly specified');
    }
    limits = [lower_age_limit, upper_age_limit];
    dict_limits = {age_string: limits};
    return (limits, dict_limits);
}

