"""
Generate an overlap table for the following prefix.
An overlap table is a table of the same size as the prefix which
informs about the potential self-overlap for each index in the prefix:
- if overlap[i] == 0, prefix[i:] can't overlap prefix[0:...]
- if overlap[i] == k with 0 < k <= i, prefix[i-k+1:i+1] overlaps with
  prefix[0:k]
"""
def _generate_overlap_table(prefix: str) -> list[int] {
    table = [0] * len(prefix);
    for i in range(1, len(prefix)) {
        idx = table[i - 1];
        while prefix[i] != prefix[idx] {
            if idx == 0 {
                table[i] = 0;
                break;
            }
            idx = table[idx - 1];
        } else {
            table[i] = idx + 1;
        }
    }
    return table;
}

"""Returns a^b in O(lg n) time complexity, where a and b are both
integers."""
def fast_exp(a: int | float, b: int | float) -> int {
    if not isinstance(a, int) == isinstance(b, int) == True {
        raise TypeError('a and b should both be integers.');
    }
    a = a as int;
    b = b as int;
    if b < 0 {
        return 0;
    }
    result = 1;
    while b != 0 {
        if (b & 1) == 1 {
            result *= a;
        }
        b >>= 1;
        a *= a;
    }
    return result;
}

"""IPv4 address filter: length > 7 and not a bogon IP. Return True if OK."""
def ipv4_filter(value: str, index: int = 0, pattern: object | None = None) -> bool {
    ip = value;
    if len(ip) < 8 {
        return False;
    }
    ip_bytes = ip.split('.');
    byte1 = int(ip_bytes[0]);
    byte2 = int(ip_bytes[1]);
    if ip.startswith('0.') {
        return False;
    }
    if ip.startswith('10.') {
        return False;
    }
    if ip.startswith('100.') and byte2 & 192 == 64 {
        return False;
    }
    if ip.startswith('127.') {
        return False;
    }
    if ip.startswith('169.254.') {
        return False;
    }
    if ip.startswith('172.') and byte2 & 240 == 16 {
        return False;
    }
    if ip.startswith('192.0.0.') {
        return False;
    }
    if ip.startswith('192.0.2.') {
        return False;
    }
    if ip.startswith('192.168.') {
        return False;
    }
    if ip.startswith('198.') and byte2 & 254 == 18 {
        return False;
    }
    if ip.startswith('198.51.100.') {
        return False;
    }
    if ip.startswith('203.0.113.') {
        return False;
    }
    if byte1 & 240 == 224 {
        return False;
    }
    if byte1 & 240 == 240 {
        return False;
    }
    if ip.endswith('.0') or ip.endswith('.255') {
        return False;
    }
    return True;
}

