"""Prime factorication."""
def prime_factors(n: int) -> list[int] {
    i = 2;
    factors: list[int] = [];
    while i * i <= n {
        if n % i {
            i += 1;
        } else {
            n //= i;
            factors.append(i);
        }
    }
    if n > 1 {
        factors.append(n);
    }
    return factors;
}

