def augmentToBeUnique(listOfItems: list[str] | None) -> list[tuple[str, int]] {
    counts: dict[str, int] = {};
    output: list[tuple[str, int]] = [];
    if listOfItems is None {
        return [];
    }
    for x in listOfItems {
        counts[x] = counts.setdefault(x, 0) + 1;
        output.append((x, counts[x] - 1));
