glob BASE_ADDRESS = 0x10000;

"""Generate C source definition for a macro listing ELF symbols."""
def CSourceForElfSymbolListMacro(
    variable_prefix: str,
    names: list[str],
    name_offsets: list[int],
    base_address: int = BASE_ADDRESS,
    symbol_size: int = 16,
    spacing_size: int = 16
) -> str {
    out = r'''// Auto-generated macro used to list all symbols
// XX must be a macro that takes the following parameters:
//   name: symbol name (quoted).
//   str_offset: symbol name offset in string table
//   address: virtual address.
//   size: size in bytes
''';
    out += '#define LIST_ELF_SYMBOLS_%s(XX) \\\n' % variable_prefix;
    address = base_address;
    for (sym, offset) in zip(names, name_offsets) {
        out += '    XX("%s", %d, 0x%x, %d) \\\n' % (sym, offset, address, symbol_size);
        address += symbol_size + spacing_size;
    }
    out += '    // END OF LIST\n';
    return out;
}

"""set a bit in a bitstring, 0 = MSB."""
def set_bitstring_bit(bitstring: bytes, bitnum: int, valuetoset: bool) -> bytes {
    bytepos = bitnum >> 3;
    bitpos = 7 - bitnum % 8;
    bytevalue = bitstring[bytepos];
    mask = 1 << bitpos;
    if valuetoset {
        if bytevalue & mask {
            return bitstring;
        }
        return (
            bitstring[:bytepos]
            + (bytevalue + mask).to_bytes(1, byteorder='big')
            + bitstring[bytepos + 1:]
        );
    }
    if bytevalue & mask {
        return (
            bitstring[:bytepos]
            + (bytevalue - mask).to_bytes(1, byteorder='big')
            + bitstring[bytepos + 1:]
        );
    }
    return bitstring;
}

"""Increments duplicates in an array until there are no duplicates."""
def increment_duplicates(arr: list[int]) -> list[int] {
    seen = set();
    for i in range(len(arr)) {
        while arr[i] in seen {
            arr[i] += 1;
        }
        seen.add(arr[i]);
    }
    return arr;
}

"""Specify an elasticsearch aggregation from schema facet configuration.
    """
def build_aggregation(
    facet_name: str,
    facet_options: dict[str, str],
    min_doc_count: int = 0
) -> tuple[str, dict[str, dict[str, str | int | list[str]]] | dict[str, dict[str, dict[str, dict[str, dict[str, str]]]]]] {
    exclude: list[str] = [];
    if facet_name == 'type' {
        field = 'embedded.@type.raw';
        exclude = ['Item'];
    } elif facet_name.startswith('audit') {
        field = facet_name;
    } else {
        field = 'embedded.' + facet_name + '.raw';
    }
    agg_name = facet_name.replace('.', '-');
    facet_type = facet_options.get('type', 'terms');
    if facet_type == 'terms' {
        agg: dict[str, dict[str, str | int | list[str]]] = {
            'terms': {'field': field, 'min_doc_count': min_doc_count, 'size': 100}
        };
        if exclude {
            agg['terms']['exclude'] = exclude;
        }
    } elif facet_type == 'exists' {
        agg = {
            'filters': {
                'filters': {
                    'yes': {'exists': {'field': field}},
                    'no': {'missing': {'field': field}}
                }
            }
        };
    } else {
        raise ValueError(
            'Unrecognized facet type {} for {} facet'.format(facet_type, field)
        );
    }
    return (agg_name, agg);
}

