""" Enclose the string argument in single quotes if it looks like it needs it.
        Spaces and quotes will trigger; single quotes in the argument are escaped.
        This is only used to compose the --print output so need only satisfy shlex.
    """
def maybe_quote(s: Any) -> object {
    NEED_QUOTE = " \t\"\\'";
    clean = True;
    for c in s {
        if (c in NEED_QUOTE) {
            clean = False;
            break;
        }
    }
    if clean {
        return s;
    }
    QUOTE = "'";
    ESC = "\\";
    arg = [QUOTE];
    for c in s {
        if (c == QUOTE) {
            arg.append(QUOTE);
            arg.append(ESC);
            arg.append(QUOTE);
        } elif (c == ESC) {
            arg.append(ESC);
        }
        arg.append(c);
    }
    arg.append(QUOTE);
    return ''.join(arg);
}

"""Joins dictionaries in a consitent way

For multiple occurences of a key the  value is defined by the first key : value pair.

Arguments:
    *args: list of parameter dictonaries

Returns:
    dict: the joined dictionary
"""
def joinParameter(*args: dict[str, str | int | float | bool]) -> dict[str, str | int | float | bool] {
    key_list = [x.keys() for x in args];
    n = len(args);
    keys = [];
    values = [];
    for i in range(n) {
        values = values + [args[i][k] for k in key_list[i] if k not in keys];
        keys = keys + [k for k in key_list[i] if k not in keys];
    }
    return {keys[i]: values[i] for i in range(len(keys))};
}

