"""
    Given :math:`U_d` and :math:`J_H`, return :math:`F_0`, :math:`F_2` and :math:`F_4`.
"""
def UdJH_to_F0F2F4(Ud: float, JH: float) -> tuple[float, float, float] {
    F0 = Ud;
    F2 = 14 / 1.625 * JH;
    F4 = 0.625 * F2;
    return (F0, F2, F4);
}

"""Merge word lines split across parenthesis continuations."""
def remove_parenthesis_break(words_list: list[list[str]]) -> list[list[str]] {
    new_words_list = [];
    parenthesis_num = 0;
    new_words = [];
    is_line_end = True;
    for words in words_list {
        if not words {
            continue;
        }
        new_words += words;
        if not words[-1].startswith("//") {
            for word in words {
                if word == "(" {
                    parenthesis_num += 1;
                } elif word == ")" {
                    parenthesis_num -= 1;
                }
            }
            is_line_end = parenthesis_num <= 0;
        } else {
            is_line_end = True;
        }
        if is_line_end {
            new_words_list.append(new_words);
            new_words = [];
        }
    }
    return new_words_list;
}

