"""
def parse_sas_token(sas_token: str) -> dict[str, str] {
    sas_data = {};
    token = sas_token.partition(' ')[2];
    for field in token.split('&') {
        (key, value) = field.split('=', 1);
        sas_data[key.lower()] = value;
    }
    return sas_data;
}

