            lines.append(line);
        }
    }
    return '\r\n'.join(lines);
}

"""A dynamic programming version of Fibonacci, linear space"""
def dp_fib_ls(n: int) -> object {
    res = [0, 1];
    for i in range(2, (n + 1)) {
        res.append((res[(i - 2)] + res[(i - 1)]));
    }
    return res[n];
}

