}

"""Identify if a point is within a grid of coordinates."""
def grid_contains_point(point_coord: list[float], grid_list_coord: list[list[float]]) -> tuple[bool, str | None] {
    is_contained = True;
    exit_msg = None;
    if float(point_coord[0]) > max(grid_list_coord[0]) {
        exit_msg = (
            'Simulation terminated: One or more sites is too '
            + 'far North and is outside the spatial bounds of '
            + 'your grid data!'
        );
        is_contained = False;
    }
    if float(point_coord[0]) < min(grid_list_coord[0]) {
        exit_msg = (
            'Simulation terminated: One or more sites is too '
            + 'far South and is outside the spatial bounds of '
            + 'your grid data!'
        );
        is_contained = False;
    }
    if float(point_coord[1]) > max(grid_list_coord[1]) {
        exit_msg = (
            'Simulation terminated: One or more sites is too '
            + 'far East and is outside the spatial bounds of '
            + 'your grid data!'
        );
        is_contained = False;
    }
    if float(point_coord[1]) < min(grid_list_coord[1]) {
        exit_msg = (
            'Simulation terminated: One or more sites is too '
            + 'far West and is outside the spatial bounds of '
            + 'your grid data!'
        );
        is_contained = False;
    }
    return (is_contained, exit_msg);
}

""" Build SQL string for fieldnames and values.

    Parameter 'row' is a dictionary, so we must keep key/value combinations
    together when constructing the string.
    """
def get_insert_string(row: Any) -> object {
    fields = "(";
    values = " VALUES(";
    for (key, val) in row.items() {
        fields = fields + key + ", ";
        if (`type(val) == int) {
            val = str(val);
        }
        values = values + "'" + val + "'" + ", ";
    }
    fields = fields[:-2] + ")";
    values = values[:-2] + ")";
    return (fields + values);
}

"""
    Find average of a list of numbers.

    Uses for loop to iterate through parameter NUMLIST
    and adds the sum of each element until the end of
    the list. AVERAGE then returns the sum divided by
    the length of NUMLIST.
    """
def average(numlist: Any) -> object {
    numlist_sum = 0;
    for num in numlist {
        numlist_sum += num;
    }
    return (numlist_sum / len(numlist));
}

