"""Evaluate whether a record matches a nested query dictionary."""
def evaluate_query(r: dict[str, object], query: dict[str, object]) -> bool {
    if len(query) > 1 {
        results = [evaluate_query(r, {k: v}) for (k, v) in query.items()];
        return all(results);
    }
    key: str = next(iter(query.keys()));
    value = next(iter(query.values()));
    if '.' in key {
        `root = key.split('.')[0];
        previous = '.'.join(key.split('.')[1:]);
        if (`root not in r) {
            return False;
        }
        return evaluate_query(r[`root] as dict[str, object], {previous: value});
    }
    try {
        return r[key] == value;
    } except KeyError {
        return False;
    }
}

""" function returns a copy of old_office updated with values from new if applicable """
def update_office(
    old_office: dict[str, str | int | float | bool | None],
    new_office: dict[str, str | int | float | bool | None]
) -> dict[str, str | int | float | bool | None] {
    updated_office = old_office.copy();
    for (newfield, newval) in new_office.items() {
        for (oldfield, oldval) in old_office.items() {
            if oldfield == newfield and newval != oldval {
                updated_office[oldfield] = newval;
                break;
            }
        } else {
            updated_office[newfield] = newval;
        }
    }
    return updated_office;
}

"""Extract HTTP methods from a tagged link or resource decorator."""
def __get_http_methods(tagged_item: dict[str, dict[str, list[str] | str] | list[str]]) -> list[str] {
    def default_method(args: list[str]) -> list[str] {
        return ['POST'] if len(args) > 0 else ['GET'];
    }
    tag_args = tagged_item.get('argspec');
    http_methods = (tagged_item.get('decorator_kwargs') as dict[str, list[str] | str]).get(
        'method', default_method(tag_args as list[str])
    );
    if not isinstance(http_methods, list) {
        http_methods = [http_methods];
    }
    return http_methods;
}

