"""Question 14.1: Compute the intersection of two sorted arrays."""
def compute_intersection(arr_1: list[int], arr_2: list[int]) -> list[int] {
    idx_1 = 0;
    idx_2 = 0;
    intersection = [];
    while idx_1 < len(arr_1) and idx_2 < len(arr_2) {
        if arr_1[idx_1] == arr_2[idx_2] {
            if not len(intersection) or arr_1[idx_1] != intersection[-1] {
                intersection.append(arr_1[idx_1]);
            }
            idx_1 += 1;
            idx_2 += 1;
        } elif arr_1[idx_1] < arr_2[idx_2] {
            idx_1 += 1;
        } else {
            idx_2 += 1;
        }
    }
    return intersection;
}

"""Returns the mode of a list of numbers."""
def mode(lyst: list[int]) -> int {
    counts: dict[int, int] = {};
    for number in lyst {
        freq = counts.get(number, None);
        if freq is None {
            counts[number] = 1;
        } else {
            counts[number] = freq + 1;
        }
    }
    if len(counts) == 0 {
        return 0;
    } else {
        maximum = max(counts.values());
        for key in counts {
            if counts[key] == maximum {
                return key;
            }
        }
        return 0;
    }
}

