    for p in properties {
        prop_array = p.split('.');
        ref = resource;
        for (pa, _) in enumerate(prop_array) {
            is_array = False;
            key = prop_array[pa];
            if key[-2:] == '[]' {
                key = key[0:len(key) - 2];
                is_array = True;
            }
            if pa == len(prop_array) - 1 {
                if properties[p] {
                    if is_array {
                        if isinstance(properties[p], str) {
                            ref[key] = properties[p].split(',');
                        } else {
                            ref[key] = properties[p];
                        }
                    } else {
                        ref[key] = properties[p];
                    }
                }
            } elif key not in ref {
                ref[key] = {};
                ref = ref[key];
            } else {
                ref = ref[key];
            }
        }
    }
    return resource;
}

""" If `str_or_list` is a list will return it as it is. If it is a str, will return a
    list with the str inside.

    Parameters
    ----------
    str_or_list: str or list

    Returns
    -------
    list
    """
def _check_list[T](str_or_list: str | list[T] | None) -> list[T] | None {
    if str_or_list is None {
        return None;
    }
    if isinstance(str_or_list, list) {
        return str_or_list;
    }
    if isinstance(str_or_list, str) {
