"""Return list of (start, end , [list of subtokens]) for each token."""
def partition_subtokens(subtokens: list[str]) -> list[tuple[int, int, list[str]]] {
    words = [];
    last = 0;
    for (i, token) in enumerate(subtokens) {
        if token[-1] == '_' {
            words.append((last, i + 1, subtokens[last:(i + 1)]));
            last = i + 1;
        }
    }
    return words;
}

"""Computes a kmer difference between two strings."""
def kdiff(str1: str, str2: str, k: int = 10) -> float {
    cnt = 0.0;
    for i in range(len(str1) - k) {
        cnt += 1 if str2.find(str1[i:(i + k)]) < 0 else 0;
    }
    return cnt / (len(str1) - k);
}

