"""Decide whether to turn on or off the sweep when single or sweep mode is selected."""
def sweep_activation_toggle(
    _: bool,
    sourced_val: float,
    meas_triggered: bool,
    swp_on: bool,
    swp_stop: float,
    swp_step: float,
    mode_choice: bool
) -> bool {
    if mode_choice is False {
        return False;
    }
    if swp_on {
        return float(sourced_val) <= float(swp_stop) - float(swp_step);
    }
    if not meas_triggered {
        return False;
    }
    return True;
}

"""
    Swap the endianness of a number
    """
def _swap_endian(val: Any, length: Any) -> object {
    if (length <= 8) {
        return val;
    }
    if (length <= 16) {
        return (((val & 65280) >> 8) | ((val & 255) << 8));
    }
    if (length <= 32) {
        return (
            ((val & 4278190080) >> 24)
            | ((val & 16711680) >> 8)
            | ((val & 65280) << 8)
            | ((val & 255) << 24)
        );
    }
    raise Exception(('Cannot swap endianness for length ' + length));
}

