"""
Helper function to return the equation of a line
passing through any two points.

Returns (slope, intercept) or (None, xposition) if the slope is infinite.
"""
def line_from_two_points(x1: float, y1: float, x2: float, y2: float) -> tuple[float, float] | tuple[None, float] {
    xdiff = x2 - x1;
    if abs(xdiff) > 0.0 {
        ydiff = y2 - y1;
        slope = ydiff / xdiff;
        intercept = y1 - slope * x1;
        return (slope, intercept);
    }
    return (None, x1);
}

"""Cut irrelevant end points, scale to pixel space and store as integer."""
def clean_strokes(sample_strokes: list[list[float | int]], factor: int = 100) -> list[list[int]] {
    copy_stroke = [];
    added_final = False;
    for stroke in sample_strokes {
        finish_flag = int(stroke[4]);
        if finish_flag == 0 {
            copy_stroke.append([
                int(round(stroke[0] * factor)),
                int(round(stroke[1] * factor)),
                int(stroke[2]),
                int(stroke[3]),
                finish_flag
            ]);
        } else {
            copy_stroke.append([0, 0, 0, 0, 1]);
            added_final = True;
            break;
        }
    }
    if not added_final {
        copy_stroke.append([0, 0, 0, 0, 1]);
    }
    return copy_stroke;
}

