"""If the keys of dict2 are a subset of the keys of dict1,
return a copy of dict1 updated with the values of dict2,
otherwise return an empty dict of the same type as dict1."""
def subset_or_none(dict1: dict[str, object], dict2: dict[str, object]) -> dict[str, object] {
    new_dict = dict1.copy();
    new_dict.update(dict2);
    if new_dict.keys() == dict1.keys() {
        return dict1.__class__(new_dict);
    }
    return dict1.__class__();
}

"""Recursive solution."""
def recursive_factorial(num: int) -> int {
    if num >= 2 {
        return num * recursive_factorial(num - 1);
    }
    return 1;
}

"""Converts a pax time to a human-readable representation"""
def pax_to_human_time(num: float) -> str {
    for x in ['ns', 'us', 'ms', 's', 'ks', 'Ms', 'G', 'T'] {
        if num < 1000.0 {
            return "%3.3f %s" % (num, x);
        }
        num /= 1000.0;
    }
    return "%3.1f %s" % (num, 's');
}

"""Check the validity of an AFM number (Greek VAT code).

  Check if input is a valid AFM number via its check digit (not if it is actually used).
  Return either True of False.
  Input should be given as a string. An integer, under certain conditions, could through an exception.
  """
def check_afm(afm: str) -> bool {
    if not isinstance(afm, str) {
        raise TypeError(
            "check_afm()",
            "You should feed to this function only strings to avoid exceptions and errors! Aborting."
        );
    }
    if len(afm) == 11 and afm[:2].upper() == "EL" {
        afm = afm[2:];
    }
    if afm.isdigit() == True and len(afm) == 9 {
        (i, sums) = (256.0, 0.0);
        for digit in afm[:-1] {
            sums += int(digit) * i;
            i /= 2;
        }
        checksum = sums % 11;
        if int(afm[-1]) == int(checksum) or (checksum == 10 and afm[-1] == "0") {
            return True;
        }
    }
    return False;
}

