""" Utility method to convert a file size in bytes to a human-readable format

    Args:
        num    (int): Number of bytes
        suffix (str): Suffix for 'bytes'

    Returns:
        str: The formatted file size as a string, eg. ``1.21 GB``
    """
def sizeof(num: int | float, suffix: str = 'B') -> str {
    for unit in ['', 'K', 'M', 'G', 'T', 'P', 'E', 'Z'] {
        if abs(num) < 1024.0 {
            return "%3.1f %s%s" % (num, unit, suffix);
        }
        num /= 1024.0;
    }
    return "%.1f %s%s" % (num, 'Y', suffix);
}

"""Create mch-filename for icon ctrl run for given leadtime.

    Args:
        lt (int): leadtime

    Returns:
        str: filename of icon output simulation in netcdf, following mch-convention

    """
def lfff_name(lt: Any) -> object {
    hour = int(lt) % 24;
    day = (int(lt) - hour) // 24;
    remaining_s = round(((lt - int(lt)) * 3600));
    sec = int((remaining_s % 60));
    mm = int(((remaining_s - sec) / 60));
    return f"lfff{day:02}{hour:02}{mm:02}{sec:02}.nc";
}

