"""Solve a dependency graph.

    Parameters
    ----------
    dependencies : dict
        For each key, the value is an iterable indicating its dependencies.
    all_members : iterable, optional
        List of all keys in the graph.
        Useful to guarantee that all keys will be in the result even
        if they are disconnected from the graph.
        (Default value: empty)

    Returns
    -------
    list of sets
        Each set contains tasks that depend only on the tasks
        in the previous set in the list.

    """
def solve_dependencies(dependencies: dict[str, list[str]], all_members: list[str] | None = None) -> list[set[str]] {
    d = {key: set(value) for (key, value) in dependencies.items()};
    if all_members {
        d.update({
            key: set()
            for key in all_members
            if key not in d
        });
    }
    r = [];
    while d {
        t = set(i for v in d.values() for i in v) - set(d.keys());
        t.update(
            k
            for (k, v) in d.items()
            if not v
        );
        r.append(t);
        d = {
            k: (v - t)
            for (k, v) in d.items()
            if v
        };
    }
    return r;
}

"""Verify the correctness of the YYC rules."""
def _check(rule1: list[int], rule2: list[list[int]]) -> bool {
    for val in rule1 {
        if val != 0 and val != 1 {
            return False;
        }
    }
    if sum(rule1) != 2 {
        return False;
    }
    if rule1[0] == rule1[1] {
        same = [0, 1, 2, 3];
    } elif rule1[0] == rule1[2] {
        same = [0, 2, 1, 3];
    } else {
        same = [0, 3, 1, 2];
    }
    for row in rule2 {
        if (
            row[same[0]] + row[same[1]] != 1
            or row[same[0]] * row[same[1]] != 0
        ) {
            return False;
        }
        if (
            row[same[2]] + row[same[3]] != 1
            or row[same[2]] * row[same[3]] != 0
        ) {
            return False;
        }
    }
    return True;
}

