"""Creates URL of Dataset.

    Example: https://data.aussda.at/dataset.xhtml?persistentId=doi:10.11587/CCESLK

    Parameters
    ----------
    base_url : str
        Base URL of Dataverse instance
    identifier : str
        Identifier of the dataset. Can be dataset id or persistent
        identifier of the dataset (e. g. doi).
    is_pid : bool
        ``True`` to use persistent identifier. ``False``, if not.

    Returns
    -------
    str
        URL of the dataset

    """
def create_dataset_url(base_url: str, identifier: str, is_pid: bool) -> str {
    assert isinstance(base_url, str);
    assert isinstance(identifier, str);
    assert isinstance(is_pid, bool);
    base_url = base_url.rstrip("/");
    if is_pid {
        url = "{0}/dataset.xhtml?persistentId={1}".format(base_url, identifier);
    } else {
        url = "{0}/dataset.xhtml?id{1}".format(base_url, identifier);
    }
    assert isinstance(url, str);
    return url;
}

"""Checks given arguments and passes correct ones to the compilation script."""
def analyze_arguments(arguments: list[str]) -> tuple[str | bool, str | bool, str, str | bool] {
    accepted_arg_prefix = [
        '--use_openbabel',
        '--use_cython',
        '--cython_compiler',
        '--overwrite'
    ];
    def _split(arg: str) -> tuple[str | None, str | None] {
        pos = arg.find('=');
        prefix = arg[:pos];
        suffix = arg[pos + 1:];
        return (None, None) if prefix not in accepted_arg_prefix else (prefix, suffix);
    }
    use_openbabel: str | bool = False;
    use_cython: str | bool = False;
    cython_compiler: str = 'msvc';
    overwrite: str | bool = False;
    if len(arguments) != 0 {
        for entry in arguments {
            data = _split(entry);
            if data[0] == '--use_cython' {
                use_cython = data[1] as str;
            } elif data[0] == '--cython_compiler' {
                cython_compiler = data[1] as str;
            } elif data[0] == '--use_openbabel' {
                use_openbabel = data[1] as str;
            } elif data[0] == '--overwrite' {
                overwrite = data[1] as str;
            }
        }
    }
    return (use_openbabel, use_cython, cython_compiler, overwrite);
}

