"""Remove intervals that are fully contained in another.

    [(10, 100), (20, 50), (70, 120), (130, 200), (10, 50), (140, 210), (150, 200)]

    results:

    [(10, 100), (70, 120), (130, 200), (140, 210)]
    """
def RemoveIntervalsContained(intervals: list[tuple[int, int]]) -> list[tuple[int, int]] {
    if not intervals {
        return [];
    }
    new_intervals = [];
    intervals.sort();
    (last_from, last_to) = intervals[0];
    for (this_from, this_to) in intervals[1:] {
        if this_from <= last_from and this_to >= last_to {
            (last_from, last_to) = (this_from, this_to);
            continue;
        }
        if last_from <= this_from and last_to >= this_to {
            continue;
        }
        new_intervals.append((last_from, last_to));
        (last_from, last_to) = (this_from, this_to);
    }
    new_intervals.append((last_from, last_to));
    return new_intervals;
}

type SchemaValue = str | int | float | list[str | int | float];

"""
    Merges two JSON schemas on a column.
    """
def merge_schemas(
    schema: dict[str, SchemaValue],
    old_schema: dict[str, SchemaValue] | None
) -> dict[str, SchemaValue] | None {
    if old_schema is None {
        return schema;
    } elif schema['type'] != old_schema['type'] {
        return old_schema;
    } elif 'enum' in schema and 'enum' in old_schema {
        merged_enum = list(old_schema['enum']);
        for enum_val in schema['enum'] {
            if enum_val not in merged_enum {
                merged_enum.append(enum_val);
            }
        }
        return dict(old_schema, enum=merged_enum);
    } elif 'inclusiveMinimum' in schema and 'inclusiveMinimum' in old_schema {
        merged_min = min(schema['inclusiveMinimum'], old_schema['inclusiveMinimum']);
        merged_max = min(schema['inclusiveMaximum'], old_schema['inclusiveMaximum']);
        return dict(
            old_schema, inclusiveMinimum=merged_min, inclusiveMaximum=merged_max
        );
    }
}

"""
    Extend the given list with the given element. If element is a scalar, it is
    appended to target; if element is a list, target is extended with it.
    >>> extend([1, 2], 4)
    [1, 2, 4]
    >>> extend([1, 2], (1, 2,))
    [1, 2, 1, 2]
    >>> extend([1, 2], {1: 2, 3: 4})
    [1, 2, {1: 2, 3: 4}]
    >>> extend([1, 2], [0, 1])
    [1, 2, 0, 1]

    :param target:
    :type target: list
    :param element:
    :rtype: list

    """
def extend(target: list[object], element: object) -> list[object] {
    assert isinstance(target, list);
    if isinstance(element, (list, tuple)) {
        target.extend(element);
    } else {
        target.append(element);
    }
    return target;
}

"""Returns the "average" of the normal distributions from NormalParameters.
NormalParameters: a list of length 2 lists, whose entries are the mean and SD of each normal distribution."""
def NormalsAverage(NormalParameters: list[tuple[float, float]]) -> list[float] {
    return [
        sum([p[0] for p in NormalParameters]) / len(NormalParameters),
        (
            sum([p[1] ** 2 for p in NormalParameters])
            / (len(NormalParameters) ** 2)
        ) ** (1 / 2)
    ];
}

