"""
    Read the bytes of the steg_bytes from the offset until the ending byte sequence is found.
    Return the bytes read and the offset of the ending byte sequence.
    """
def read_until(steg_bytes: bytes, offset: int, ending: str) -> tuple[bytes, int] | None {
    bytes_read = b'';
    while offset < len(steg_bytes) {
        if steg_bytes[offset:(offset + len(ending))] == ending.encode() {
            return (bytes_read, offset);
        }
        bytes_read += steg_bytes[offset:(offset + 1)];
        offset += 1;
    }
}

"""
    Expected format: `<channel_id>,<from_addr>,<api_url>;<channel_id>,<from_addr>,<api_url>;`

    Returns a tuple.
    The first item is the assumed default junebug channel which can be used as a
    default fallback for JUNEBUG_DEFAULT_CHANNEL_ID.
    The second item is the dictionary that can be passed to JUNEBUG_CHANNELS
    """
def parse_channel_info(data: str) -> tuple[str | None, dict[str, dict[str, str]]] {
    channels: dict[str, dict[str, str]] = {};
    default_channel_id: str | None = None;
    for channel in data.strip().split(';') {
        (channel_id, from_addr, api_url) = channel.split(',');
        if not default_channel_id {
            default_channel_id = channel_id.strip();
        }
        channels[channel_id.strip()] = {
            'FROM_ADDRESS': from_addr.strip(),
            'API_URL': api_url.strip()
        };
    }
    return (default_channel_id, channels);
}

"""Eats a list of items, groups consecutive items in separate lists and
        returns a list of lists."""
def build_ranges(page_list: list[int | str]) -> str {
    page_list.append(-1);
    output = [];
    last = int(page_list[0]) - 1;
    beginning = int(page_list[0]);
    for i in page_list {
        i = int(i);
        if i != last + 1 {
            output.append([str(beginning), str(last)]);
            beginning = i;
        }
        last = i;
    }
    page_list.pop();
    return ",".join(["-".join(x) for x in output]);
}

