"""Given a class name (aaaUserEp) returns tuple aaa,UserEp"""
def parseMoClassName(className: str) -> tuple[str, str] {
    idx = -1;
    upper_found = False;
    for c in className {
        idx += 1;
        if c.isupper() {
            upper_found = True;
            break;
        }
    }
    if upper_found {
        pkg = className[:idx];
        klass = className[idx:];
    } else {
        pkg = className;
        klass = "";
    }
    return (pkg, klass);
}

"""Sum integers."""
def add_integers(*args: int) -> int {
    if not len(args) {
        raise TypeError(f"{add_integers.__name__}() requires at least one argument");
    }
    for i in args {
        if not isinstance(i, int) {
            raise TypeError(
                f"Passed argument of type '{type(i).__name__}', but only integers allowed: {i}"
            );
        }
    }
    return sum(args);
}

"""Compare versions the way chrome does."""
def cmpversion(a: str, b: str) -> bool {
    def split_version(v: str) -> list[str] | tuple[str, str] {
        if '.' in v {
            return v.split('.', 1);
        }
        if '_' in v {
            return v.split('_', 1);
        }
        return (v, '0');
    }
    (a_maj, a_min) = split_version(a);
    (b_maj, b_min) = split_version(b);
    if a_maj == b_maj {
        return cmpversion(a_min, b_min);
    }
    return int(a_maj) > int(b_maj);
}

